#!/usr/bin/env python3
"""Offline suite for workers_standards_guard.py: builds a throwaway git repo and checks that added anti-patterns fail, existing ones and
marked false positives pass, and observability removal / bare new workers fail."""
import os, subprocess, sys, tempfile, pathlib
G = str(pathlib.Path(__file__).resolve().parent / "workers_standards_guard.py")
fails = 0
def sh(cwd, *a): subprocess.run(a, cwd=cwd, check=True, capture_output=True)
def guard(cwd): return subprocess.run([sys.executable, G, "HEAD"], cwd=cwd, capture_output=True, text=True)
def ok(c, m):
    global fails
    if not c: fails += 1; print("FAIL " + m)
with tempfile.TemporaryDirectory() as t:
    p = pathlib.Path(t); sh(t, "git", "init", "-q"); sh(t, "git", "config", "user.email", "a@b.c"); sh(t, "git", "config", "user.name", "t")
    (p / "w").mkdir()
    (p / "w/worker.js").write_text('const id = Math.random().toString(36).slice(2);\nexport default {};\n')
    (p / "w/wrangler.toml").write_text('name="w"\n[observability]\nenabled=true\n[observability.traces]\nenabled=true\n')
    sh(t, "git", "add", "-A"); sh(t, "git", "commit", "-qm", "base")
    r = guard(t); ok(r.returncode == 0, "no change passes (existing debt is not blocked): " + r.stdout)
    (p / "w/worker.js").write_text('const id = Math.random().toString(36).slice(2);\nexport default {};\nconst t2 = Math.random().toString(16).slice(2);\n')
    r = guard(t); ok(r.returncode == 1 and "math-random-token" in r.stdout and "w/worker.js:3" in r.stdout, "an added Math.random id fails with its line: " + r.stdout)
    (p / "w/worker.js").write_text('export default {};\nconst t2 = Math.random().toString(16).slice(2); // standards-ok: jitter label, not a secret\n')
    r = guard(t); ok(r.returncode == 0, "a marked false positive passes: " + r.stdout)
    (p / "w/worker.js").write_text('export default {};\nif (req.headers.get("x") !== env.LOOP_TOKEN) return new Response("no");\nctx.passThroughOnException();\n')
    r = guard(t); ok(r.returncode == 1 and "secret-compare" in r.stdout and "pass-through-on-exception" in r.stdout, "secret compare and passThroughOnException fail: " + r.stdout)
    sh(t, "git", "checkout", "--", "w/worker.js")
    (p / "w/wrangler.toml").write_text('name="w"\n')
    r = guard(t); ok(r.returncode == 1 and "observability-removed" in r.stdout, "removing observability fails: " + r.stdout)
    sh(t, "git", "checkout", "--", "w/wrangler.toml")
    (p / "n").mkdir(); (p / "n/wrangler.toml").write_text('name="n"\n'); (p / "n/worker.js").write_text("export default {};\n")
    sh(t, "git", "add", "-A"); r = guard(t); ok(r.returncode == 1 and "new-worker-observability" in r.stdout, "a new worker without observability fails: " + r.stdout)
    (p / "n/wrangler.toml").write_text('name="n"\n[observability]\nenabled=true\nhead_sampling_rate=1\n[observability.traces]\nenabled=true\n')
    sh(t, "git", "add", "-A"); r = guard(t); ok(r.returncode == 0, "a new worker with observability and traces passes: " + r.stdout)
    (p / "n/RETIRED").write_text("x"); (p / "n/worker.js").write_text("ctx.passThroughOnException();\n")
    r = guard(t); ok(r.returncode == 0, "retired workers are skipped: " + r.stdout)
# MERGE-BASE-1: main advancing after the branch point must not blame the change for main's newer commits
with tempfile.TemporaryDirectory() as t2:
    q = pathlib.Path(t2); sh(t2, "git", "init", "-q", "-b", "main"); sh(t2, "git", "config", "user.email", "a@b.c"); sh(t2, "git", "config", "user.name", "t")
    (q / "w").mkdir(); (q / "w/worker.js").write_text("export default {};\nconst k = req.h !== env.LOOP_TOKEN;\n"); (q / "w/wrangler.toml").write_text('[observability]\n[observability.traces]\n')
    sh(t2, "git", "add", "-A"); sh(t2, "git", "commit", "-qm", "base"); sh(t2, "git", "checkout", "-q", "-b", "feature")
    (q / "x").mkdir(); (q / "x/worker.js").write_text("export default {};\n"); (q / "x/wrangler.toml").write_text('[observability]\nenabled=true\nhead_sampling_rate=1\n[observability.traces]\nenabled=true\n')
    sh(t2, "git", "add", "-A"); sh(t2, "git", "commit", "-qm", "feature"); sh(t2, "git", "checkout", "-q", "main")
    (q / "w/worker.js").write_text("export default {};\n"); sh(t2, "git", "commit", "-qam", "main fixes the compare"); sh(t2, "git", "checkout", "-q", "feature")
    r = subprocess.run([sys.executable, G, "main"], cwd=t2, capture_output=True, text=True)
    ok(r.returncode == 0, "a base that moved on (it removed a pattern the branch still has) does not fail the branch: " + r.stdout)
# WORKERS-STANDARDS-GUARD-2: floating promises, id assignments, loose secret compares, ctx in a signature, queue DLQ, logs+traces, allowlist
import importlib.util
spec = importlib.util.spec_from_file_location("wsg", G); W = importlib.util.module_from_spec(spec); spec.loader.exec_module(W)
def rules(text, full=None): return sorted({v[0] for v in W.check_code([(len(full) if full else 1, text)], full)})
ok(rules('  fetch("https://x.example/hook", { method: "POST" });') == ["floating-promise"], "a bare fetch statement floats")
ok(rules('  env.DB.prepare("UPDATE t SET a = 1").run();') == ["floating-promise"], "a bare D1 run floats")
ok(rules('  env.DB.prepare("UPDATE t SET a = ?1").bind(x).run();') == ["floating-promise"], "a bare bound D1 run floats")
ok(rules('  env.CACHE.put(key, value, { expirationTtl: 60 });') == ["floating-promise"], "a bare KV put floats")
ok(rules('  env.JOBS.send({ id: 1 });') == ["floating-promise"], "a bare queue send floats")
for good in ['  await fetch(url);', '  return env.DB.prepare(q).run();', '  ctx.waitUntil(env.CACHE.put(k, v));', '  const r = env.DB.prepare(q).run();',
             '  void fetch(url);', '  p = fetch(url);', '  env.DB.prepare(q).run().then(done)', '  if (x) await env.JOBS.send(m);', '  const stmt = env.DB.prepare(q);']:
    ok(rules(good) == [], "consumed or non-statement promise passes: " + good)
ok(rules('    env.CACHE.put(k, v);', ['  ctx.waitUntil(', '    env.CACHE.put(k, v);']) == [], "a call on the line after `waitUntil(` is its argument")
ok(rules('    fetch(url);', ['  const r = await', '    fetch(url);']) == [], "a call on the line after `await` is awaited")
ok(rules('    fetch(url);', ['  log("x"); // see https://a.example/b', '    fetch(url);']) == ["floating-promise"], "a closed previous line does not consume the call")
ok(rules('  const sessionId = "s" + Math.random();') == ["math-random-token"], "Math.random assigned to an id name")
ok(rules('  out.push({ token: String(Math.random()) });') == ["math-random-token"], "Math.random assigned to a token property")
ok(rules('  const nonce = Math.floor(Math.random() * 1e9);') == ["math-random-token"], "Math.random assigned to a nonce")
for good in ['  const jitter = Math.random() * 500;', '  if (Math.random() < 0.1) sample();', '  const valid = Math.random() > 0.5;', '  const delayMs = base * (1 + Math.random());', '  const idx = Math.floor(Math.random() * list.length);']:
    ok(rules(good) == [], "jitter and sampling pass: " + good)
ok(rules('  if (tok == env.ADMIN_KEY) go();') == ["secret-compare"] and rules('  if (env.HOOK_SECRET != sig) no();') == ["secret-compare"], "loose equality against a secret is a compare")
for good in ['  if (env.LOOP_TOKEN === undefined) return off();', '  if (env.API_KEY == null) return;', '  const has = env.ROUTER_AUTH_KEY !== "";', '  if (!env.LOOP_TOKEN) return;', '  if (await timingSafeEqual(tok, env.LOOP_TOKEN)) go();', '  if (env.MODE === "x") go();']:
    ok(rules(good) == [], "a presence test or constant-time compare passes: " + good)
ok(rules('  async fetch(request, env, { waitUntil }) {') == ["destructured-ctx"], "ctx destructured in a handler signature")
ok(rules('  const { waitUntil } = this.ctx;') == ["destructured-ctx"], "ctx destructured from this.ctx")
ok(rules('  ctx.passThroughOnException();') == ["pass-through-on-exception"], "a passThroughOnException call fails")
ok(rules('  await mod.scheduled(c, env, { waitUntil: function (p) { pending.push(p); }, passThroughOnException: function () {} });') == [], "the no-op member of a folded-member stub ctx passes")
ok(rules('  // fetch(url);') == [] and rules('  fetch(url); // standards-ok: fire-and-forget beacon, reviewed') == [], "comments and marked lines pass")
ok(W.obs_state('[observability]\nenabled = true\n[observability.traces]\nenabled = true\n') == (True, True), "logs and traces on")
ok(W.obs_state('[observability]\nenabled = true\n') == (True, False), "the top-level switch alone does not enable traces")
ok(W.obs_state('[observability]\nenabled = true\n[observability.logs]\nenabled = false\n[observability.traces]\nenabled = true\n') == (False, True), "logs switched off")
ok(W.obs_state('# [observability.traces]\n# enabled = true\n[observability.logs]\nenabled = true\n') == (True, False), "a commented block does not count")
ok(W.consumers('[[queues.consumers]]\nqueue = "a"\nmax_retries = 3\n\n[[queues.consumers]]\nqueue = "b"\ndead_letter_queue = "b-dlq"\n[vars]\nX = "1"\n') == {"a": False, "b": True}, "consumers: one without and one with a dead-letter queue")
al = pathlib.Path(tempfile.mkdtemp()) / "allow.txt"
al.write_text("# comment\nw/worker.js floating-promise fetch(BEACON) # reviewed 2026-10-12: beacon, loss accepted\nw/worker.js secret-compare no-reason-given\nw/wrangler.toml * queue = \"a\" # legacy consumer\n")
A = W.load_allowlist(str(al))
ok(len(A) == 2, "an allowlist line without a reason is ignored: " + repr(A))
ok(W.allowed(A, "w/worker.js", "floating-promise", "  fetch(BEACON);") and not W.allowed(A, "w/worker.js", "floating-promise", "  fetch(other);") and not W.allowed(A, "x/worker.js", "floating-promise", "  fetch(BEACON);") and W.allowed(A, "w/wrangler.toml", "queue-consumer-no-dlq", 'queue = "a"'), "allowlist matches path, rule and text")
OBS = '[observability]\nenabled = true\n[observability.traces]\nenabled = true\n'
with tempfile.TemporaryDirectory() as t3:
    p = pathlib.Path(t3); sh(t3, "git", "init", "-q"); sh(t3, "git", "config", "user.email", "a@b.c"); sh(t3, "git", "config", "user.name", "t")
    for d in ("w", "old", "q"): (p / d).mkdir()
    (p / "w/worker.js").write_text("export default {};\n"); (p / "w/wrangler.toml").write_text('name = "w"\n' + OBS)
    (p / "old/wrangler.toml").write_text('name = "old"\ncompatibility_date = "2026-08-01"\n[observability]\nenabled = true\n')
    (p / "q/wrangler.toml").write_text('name = "q"\n' + OBS + '[[queues.consumers]]\nqueue = "legacy"\n')
    sh(t3, "git", "add", "-A"); sh(t3, "git", "commit", "-qm", "base")
    (p / "w/worker.js").write_text('export default {};\nfunction f(env, u) {\n  fetch(u);\n  env.DB.prepare("x").run();\n}\n')
    r = guard(t3); ok(r.returncode == 1 and r.stdout.count("[floating-promise]") == 2 and "w/worker.js:3" in r.stdout and "w/worker.js:4" in r.stdout, "added floating promises fail with their lines: " + r.stdout)
    sh(t3, "git", "checkout", "--", "w/worker.js")
    (p / "old/wrangler.toml").write_text('name = "old"\ncompatibility_date = "2026-10-01"\n[observability]\nenabled = true\n')
    r = guard(t3); ok(r.returncode == 0, "an unrelated edit of a config without traces passes (existing debt): " + r.stdout)
    (p / "old/wrangler.toml").write_text('name = "old"\ncompatibility_date = "2026-08-01"\n[observability]\nenabled = true\nhead_sampling_rate = 1\n')
    r = guard(t3); ok(r.returncode == 1 and "observability-incomplete" in r.stdout, "editing [observability] and leaving it without traces fails: " + r.stdout)
    (p / "old/wrangler.toml").write_text('name = "old"\ncompatibility_date = "2026-08-01"\n[observability]\nenabled = true\n[observability.traces]\nenabled = true\n')
    r = guard(t3); ok(r.returncode == 0, "adding traces passes: " + r.stdout)
    sh(t3, "git", "checkout", "--", "old/wrangler.toml")
    (p / "w/wrangler.toml").write_text('name = "w"\n[observability]\nenabled = true\n[observability.traces]\nenabled = false\n')
    r = guard(t3); ok(r.returncode == 1 and "observability-disabled" in r.stdout, "switching traces off fails: " + r.stdout)
    (p / "w/wrangler.toml").write_text('name = "w"\n' + OBS + '[[queues.consumers]]\nqueue = "jobs"\nmax_retries = 5\n')
    r = guard(t3); ok(r.returncode == 1 and "queue-consumer-no-dlq" in r.stdout and "jobs" in r.stdout, "a new consumer without a dead-letter queue fails: " + r.stdout)
    (p / "w/wrangler.toml").write_text('name = "w"\n' + OBS + '[[queues.consumers]]\nqueue = "jobs"\nmax_retries = 5\ndead_letter_queue = "jobs-dlq"\n')
    r = guard(t3); ok(r.returncode == 0, "a consumer with a dead-letter queue passes: " + r.stdout)
    sh(t3, "git", "checkout", "--", "w/wrangler.toml")
    (p / "q/wrangler.toml").write_text('name = "q"\n# touched\n' + OBS + '[[queues.consumers]]\nqueue = "legacy"\n')
    r = guard(t3); ok(r.returncode == 0, "an existing consumer without a dead-letter queue is existing debt: " + r.stdout)
    sh(t3, "git", "checkout", "--", "q/wrangler.toml")
    (p / "n").mkdir(); (p / "n/worker.js").write_text("export default {};\n"); (p / "n/wrangler.toml").write_text('name = "n"\n[observability]\nenabled = true\n[observability.traces]\nenabled = false\n')
    sh(t3, "git", "add", "-A"); r = guard(t3); ok(r.returncode == 1 and "new-worker-observability" in r.stdout, "a new worker with traces declared but off fails: " + r.stdout)
    sh(t3, "git", "rm", "-rqf", "n")
    # WORKERS-STANDARDS-GUARD-3: config shapes judged on what the change adds
    (p / "w/wrangler.toml").write_text('name = "w"\n' + OBS + '[[send_email]]\nname = "MAIL"\n')
    r = guard(t3); ok(r.returncode == 1 and "send-email-unrestricted" in r.stdout, "a new unrestricted send_email binding fails: " + r.stdout)
    (p / "w/wrangler.toml").write_text('name = "w"\n' + OBS + '[[send_email]]\nname = "MAIL"\nallowed_sender_addresses = ["noreply@example.org"]\n')
    r = guard(t3); ok(r.returncode == 0, "a send_email binding with a sender restriction passes: " + r.stdout)
    (p / "w/wrangler.toml").write_text('name = "w"\n' + OBS + '[[migrations]]\ntag = "v1"\nnew_classes = ["Thing"]\n')
    r = guard(t3); ok(r.returncode == 1 and "legacy-do-storage" in r.stdout, "new_classes (KV-backed Durable Object storage) fails: " + r.stdout)
    (p / "w/wrangler.toml").write_text('name = "w"\n' + OBS + '[[migrations]]\ntag = "v1"\nnew_sqlite_classes = ["Thing"]\n')
    r = guard(t3); ok(r.returncode == 0, "new_sqlite_classes passes: " + r.stdout)
    sh(t3, "git", "checkout", "--", "w/wrangler.toml")
    (p / "old/worker.js").write_text('import { Buffer } from "node:buffer";\nexport default {};\n'); sh(t3, "git", "add", "-A"); sh(t3, "git", "commit", "-qm", "node import")
    (p / "old/wrangler.toml").write_text('name = "old"\ncompatibility_date = "2026-10-10"\ncompatibility_flags = ["no_nodejs_compat", "no_nodejs_compat_v2"]\n[observability]\nenabled = true\n')
    r = guard(t3); ok(r.returncode == 1 and "node-opt-out-with-imports" in r.stdout, "crossing 2026-08-04 with a node opt-out while importing node:* fails: " + r.stdout)
    (p / "old/wrangler.toml").write_text('name = "old"\ncompatibility_date = "2026-10-10"\n[observability]\nenabled = true\n')
    r = guard(t3); ok(r.returncode == 0, "crossing 2026-08-04 without the opt-out passes (nodejs_compat is then the default): " + r.stdout)
    sh(t3, "git", "checkout", "--", "old/wrangler.toml")
# WORKERS-STANDARDS-GUARD-3 code rules
ok(rules('  const r = await env.DB.prepare(`SELECT * FROM t WHERE id = ${id}`).all();') == ["interpolated-sql"], "SQL built by interpolation fails")
ok(rules('  const r = await env.DB.prepare(`SELECT * FROM t WHERE id = ?1`).bind(id).all();') == [] and rules('  const r = await env.DB.prepare("SELECT " + cols + " FROM t").all();') == [], "a bound template literal and a column-list concatenation pass")
ok(rules('  p.catch(function () {});') == ["swallowed-catch"] and rules('  p.catch(() => {});') == ["swallowed-catch"] and rules('  p.catch(e => {});') == ["swallowed-catch"], "an empty .catch handler fails")
ok(rules('  try { await x(); } catch (e) {}') == ["swallowed-catch"] and rules('  } catch {}') == ["swallowed-catch"], "an empty catch block fails")
for good in ['  } catch (e) { console.error(JSON.stringify({ evt: "x", error: String(e) })); }', '  p.catch(function (e) { log(e); });', '  } catch (e) { return null; }',
             '  p.catch(function () {}); // standards-ok: beacon, loss accepted']:
    ok(rules(good) == [], "a handled, logged or marked catch passes: " + good)
ok(rules('  const text = res.response.trim();') == ["ai-response-string-assumption"], "a string method on a Workers AI response fails")
ok(rules('  const text = typeof res.response === "string" ? res.response.trim() : JSON.stringify(res.response);') == [], "a typeof-guarded response passes")
ok(W.unrestricted_send_email('[[send_email]]\nname = "A"\n\n[[send_email]]\nname = "B"\ndestination_address = "x@y.z"\n[vars]\n') .__len__() == 1, "one of two send_email blocks is unrestricted")
print("workers_standards_guard: %s" %("FAILED %d" % fails if fails else "all passed")); sys.exit(1 if fails else 0)
